var MINUTO5 = 6e4;
var PICKUP_SLOT_REASONS = ["min_notice", "slot_full"];
function pickupSlots(config2, takeaway, date5, now, ordersBySlot, staff = false) {
  const franjas = franjasDelDia({ ...config2, pasoMinutos: takeaway.stepMinutes }, date5);
  return franjas.map((f) => {
    const orders = ordersBySlot[f.inicio] ?? 0;
    let reason = null;
    if (f.inicio < now + takeaway.minNoticeMinutes * MINUTO5) reason = "min_notice";
    else if (orders >= takeaway.maxOrdersPerSlot) reason = "slot_full";
    const pasada = f.inicio < now;
    return {
      time: f.hora,
      wallDate: f.fecha,
      startAt: f.inicio,
      shift: f.turno,
      available: staff ? !pasada : reason === null,
      reason,
      orders
    };
  });
}
function findPickupSlot(slots, time3) {
  const s = slots.find((x) => x.time === time3);
  return s && s.available ? s : null;
}
function takeawayLabel(guestName, pickupTime) {
  const nombre = guestName.trim().split(/\s+/)[0] ?? guestName;
  return `Para llevar \xB7 ${nombre} \xB7 ${pickupTime}`.slice(0, 80);
}

